import{_ as a,c as i,o as t,j as n,Y as l,t as h}from"./chunks/framework.D-NV0Bun.js";const g=JSON.parse('{"title":"slabinfo | x-cmd man (man5) | kernel slab allocator statistics","titleTemplate":false,"description":"x-cmd man (man5 Manual Page) | slabinfo - kernel slab allocator statistics","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"slabinfo | x-cmd man (man5) | kernel slab allocator statistics"}],["meta",{"name":"og:description","content":"x-cmd man (man5 Manual Page) | slabinfo - kernel slab allocator statistics"}]]},"headers":[],"params":{"isMan":true,"man":"slabinfo","category":"man5","desc":"kernel slab allocator statistics"},"relativePath":"man5/slabinfo.md","filePath":"man5/[man].md"}'),d={name:"man5/slabinfo.md"},o={class:"visually-hidden"};function r(e,s,p,c,k,m){return t(),i("div",null,[n("h1",o,h(e.$params.man),1),s[0]||(s[0]=l(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>slabinfo - kernel slab allocator statistics</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /proc/slabinfo</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Frequently used objects in the Linux kernel (buffer heads, inodes, dentries, etc.) have their own cache. The file <em>/proc/slabinfo</em> gives statistics on these caches. The following (edited) output shows an example of the contents of this file:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /proc/slabinfo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">slabinfo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2.1</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># name&lt;active_objs&gt; &lt;num_objs&gt; &lt;objsize&gt; &lt;objperslab&gt; &lt;pagesperslab&gt; ...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sigqueue</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  100</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  100</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  160</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   25</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tunables</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> slabdata</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   4</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   4</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sighand_cache</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 355</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   405</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2112</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  15</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  8</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tunables</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> slabdata</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  27</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  27</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kmalloc-8192</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   96</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   96</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  8192</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   4</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  8</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tunables</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> slabdata</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  24</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  24</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  0</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span></span></code></pre></div><p>The first line of output includes a version number, which allows an application that is reading the file to handle changes in the file format. (See VERSIONS, below.) The next line lists the names of the columns in the remaining lines.</p><p>Each of the remaining lines displays information about a specified cache. Following the cache name, the output shown in each line shows three components for each cache:</p><ul><li><p>statistics</p></li><li><p>tunables</p></li><li><p>slabdata</p></li></ul><p>The statistics are as follows:</p><dl><dt><em>active_objs</em></dt><dd>The number of objects that are currently active (i.e., in use).</dd><dt><em>num_objs</em></dt><dd>The total number of allocated objects (i.e., objects that are both in use and not in use).</dd><dt><em>objsize</em></dt><dd>The size of objects in this slab, in bytes.</dd><dt><em>objperslab</em></dt><dd>The number of objects stored in each slab.</dd><dt><em>pagesperslab</em></dt><dd>The number of pages allocated for each slab.</dd></dl><p>The <em>tunables</em> entries in each line show tunable parameters for the corresponding cache. When using the default SLUB allocator, there are no tunables, the <em>/proc/slabinfo</em> file is not writable, and the value 0 is shown in these fields. When using the older SLAB allocator, the tunables for a particular cache can be set by writing lines of the following form to <em>/proc/slabinfo</em>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># echo &#39;name limit batchcount sharedfactor&#39; &gt; /proc/slabinfo</span></span></code></pre></div><p>Here, <em>name</em> is the cache name, and <em>limit</em>, <em>batchcount</em>, and <em>sharedfactor</em> are integers defining new values for the corresponding tunables. The <em>limit</em> value should be a positive value, <em>batchcount</em> should be a positive value that is less than or equal to <em>limit</em>, and <em>sharedfactor</em> should be nonnegative. If any of the specified values is invalid, the cache settings are left unchanged.</p><p>The <em>tunables</em> entries in each line contain the following fields:</p><dl><dt><em>limit</em></dt><dd>The maximum number of objects that will be cached.</dd><dt><em>batchcount</em></dt><dd>On SMP systems, this specifies the number of objects to transfer at one time when refilling the available object list.</dd><dt><em>sharedfactor</em></dt><dd>[To be documented]</dd></dl><p>The <em>slabdata</em> entries in each line contain the following fields:</p><dl><dt><em>active_slabs</em></dt><dd>The number of active slabs.</dd><dt><em>nums_slabs</em></dt><dd>The total number of slabs.</dd><dt><em>sharedavail</em></dt><dd>[To be documented]</dd></dl><p>Note that because of object alignment and slab cache overhead, objects are not normally packed tightly into pages. Pages with even one in-use object are considered in-use and cannot be freed.</p><p>Kernels configured with <strong>CONFIG_DEBUG_SLAB</strong> will also have additional statistics fields in each line, and the first line of the file will contain the string &quot;(statistics)&quot;. The statistics field include : the high water mark of active objects; the number of times objects have been allocated; the number of times the cache has grown (new pages added to this cache); the number of times the cache has been reaped (unused pages removed from this cache); and the number of times there was an error allocating new pages to this cache.</p><h2 id="versions" tabindex="-1">VERSIONS <a class="header-anchor" href="#versions" aria-label="Permalink to &quot;VERSIONS&quot;">​</a></h2><p>The <em>/proc/slabinfo</em> file first appeared in Linux 2.1.23. The file is versioned, and over time there have been a number of versions with different layouts:</p><dl><dt>1.0</dt><dd>Present throughout the Linux 2.2.x kernel series.</dd><dt>1.1</dt><dd>Present in the Linux 2.4.x kernel series.</dd><dt>1.2</dt><dd>A format that was briefly present in the Linux 2.5 development series.</dd><dt>2.0</dt><dd>Present in Linux 2.6.x kernels up to and including Linux 2.6.9.</dd><dt>2.1</dt><dd>The current format, which first appeared in Linux 2.6.10.</dd></dl><h2 id="notes" tabindex="-1">NOTES <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;NOTES&quot;">​</a></h2><p>Only root can read and (if the kernel was configured with <strong>CONFIG_SLAB</strong>) write the <em>/proc/slabinfo</em> file.</p><p>The total amount of memory allocated to the SLAB/SLUB cache is shown in the <em>Slab</em> field of <em>/proc/meminfo</em>.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>slabtop</strong>(1)</p><p>The kernel source file <em>Documentation/vm/slub.txt</em> and <em>tools/vm/slabinfo.c</em>.</p>`,30))])}const F=a(d,[["render",r]]);export{g as __pageData,F as default};
